//! 31 国本地化 / i18n module。
//!
//! 启动时从 `LANG` / `LC_ALL` / `LC_MESSAGES` 环境变量自动识别 locale,
//! 把硬编码英文菜单/UI 字符串翻译成对应语言。无匹配时 fallback 回英文。
//!
//! 集成点:`commands.rs` 在调用 macOS NSMenu API 前用 `t(&cmd.menubar[0])`
//! 等包一层翻译。`WezTerm`(品牌名)不翻译。
//!
//! 支持的 31 个 locale:
//! - en(默认 fallback)
//! - zh-CN, zh-TW, ja, ko        # 东亚
//! - fr, de, es, pt-BR, it       # 西欧
//! - ru, uk, pl, cs, hu, ro      # 东欧
//! - nl, sv, nb, da, fi, el      # 北欧 / 希腊
//! - ar, he, tr                  # 中东
//! - hi, id, ms, fil, vi, th     # 南亚 / 东南亚

use std::collections::HashMap;
use std::sync::OnceLock;

/// 主翻译表:locale → (英文 key → 译文)
fn translation_table() -> &'static HashMap<&'static str, HashMap<&'static str, &'static str>> {
    static TABLE: OnceLock<HashMap<&'static str, HashMap<&'static str, &'static str>>> =
        OnceLock::new();
    TABLE.get_or_init(build_table)
}

/// 翻译入口:`t("Shell")` 在中文 locale 下返回 "外壳"。
/// 无匹配时返回原 key(fallback 到英文)。
///
/// commands.rs 里部分 brief 是动态拼接的(如
/// `format!("Activate {ordinal} Tab")` 产出 "Activate 1st Tab" /
/// "Activate 8th Tab"),静态查表无法命中。在静态查表 miss 后
/// 走 try_dynamic_ordinal,识别 "Activate Nth Tab/Pane/Window"
/// 这类英文模板,提取数字后用本地化模板回填。
pub fn t(key: &str) -> String {
    let locale = current_locale();
    let prefix = locale.split('-').next().unwrap_or("");
    if let Some(map) = translation_table().get(locale.as_str()) {
        if let Some(v) = map.get(key) {
            return (*v).to_string();
        }
    }
    if !prefix.is_empty() && prefix != locale.as_str() {
        if let Some(map) = translation_table().get(prefix) {
            if let Some(v) = map.get(key) {
                return (*v).to_string();
            }
        }
    }
    // 动态 ordinal 模式
    if let Some(out) = try_dynamic_ordinal(key, &locale) {
        return out;
    }
    if !prefix.is_empty() && prefix != locale.as_str() {
        if let Some(out) = try_dynamic_ordinal(key, prefix) {
            return out;
        }
    }
    // 通用 substring 模板:strip_prefix + strip_suffix 抓中间任意值,
    // 用 ORDINAL_TEMPLATES 里 _tpl_subst_* 模板回填
    if let Some(out) = try_dynamic_subst(key, &locale) {
        return out;
    }
    if !prefix.is_empty() && prefix != locale.as_str() {
        if let Some(out) = try_dynamic_subst(key, prefix) {
            return out;
        }
    }
    key.to_string()
}

/// 处理 "New Tab (Domain X)" / "New Tab (`X` Domain)" 等 brief
/// 中间夹任意值的模板。与 ordinal 不同,这里 X 是字符串(域名/标签)
/// 而不是整数,无需校验后缀。
fn try_dynamic_subst(key: &str, locale: &str) -> Option<String> {
    const PATTERNS: &[(&str, &str, &str)] = &[
        // 顺序敏感:更具体的(带 ` 反引号 / "with id")放前面,
        // 否则 "New Tab (Domain " 会先吃掉 "with id" 形式的前缀。
        ("New Tab (Domain with id ", ")", "_tpl_new_tab_domain_id"),
        ("New Tab (`", "` Domain)", "_tpl_new_tab_domain_name"),
        ("New Tab (Domain ", ")", "_tpl_new_tab_domain_label"),
        ("Attach Domain ", "", "_tpl_attach_domain_label"),
        ("Detach Domain ", "", "_tpl_detach_domain_label"),
        ("Open ", " in your browser", "_tpl_open_in_browser"),
        // Resize Pane N cell(s) ... — 4 个方向,共享前缀
        ("Resize Pane ", " cell(s) to the Left", "_tpl_resize_pane_left"),
        ("Resize Pane ", " cell(s) to the Right", "_tpl_resize_pane_right"),
        ("Resize Pane ", " cell(s) Upwards", "_tpl_resize_pane_up"),
        ("Resize Pane ", " cell(s) Downwards", "_tpl_resize_pane_down"),
        // Move tab N place(s) to the left/right
        ("Move tab ", " place(s) to the left", "_tpl_move_tab_left"),
        ("Move tab ", " place(s) to the right", "_tpl_move_tab_right"),
        ("Move tab to index ", "", "_tpl_move_tab_to_index"),
        // Scroll Down/Up N Page(s) - 大写
        ("Scroll Down ", " Page(s)", "_tpl_scroll_down_pages"),
        ("Scroll Up ", " Page(s)", "_tpl_scroll_up_pages"),
        // Scroll up/down N line(s)/prompt(s) - 小写 direction
        ("Scroll up ", " line(s)", "_tpl_scroll_up_lines"),
        ("Scroll down ", " line(s)", "_tpl_scroll_down_lines"),
        ("Scroll up ", " prompt(s)", "_tpl_scroll_up_prompts"),
        ("Scroll down ", " prompt(s)", "_tpl_scroll_down_prompts"),
        // Switch to workspace
        ("Switch to workspace ", "", "_tpl_switch_to_workspace"),
        // Spawn the X into a new workspace
        ("Spawn the ", " into a new workspace and switch to it", "_tpl_spawn_workspace"),
        // Activate key table / Attach domain `name` / Detach the `name` domain / Detach with id / Emit event
        ("Activate key table `", "`", "_tpl_activate_keytable"),
        ("Attach domain `", "`", "_tpl_attach_domain_name"),
        ("Detach the `", "` domain", "_tpl_detach_named_domain"),
        ("Detach the domain with id ", "", "_tpl_detach_domain_with_id"),
        ("Emit event `", "`", "_tpl_emit_event"),
        ("Completes selection, and copy ", "", "_tpl_completes_selection_copy"),
        // tooltip(doc) 用的 subst 模板
        ("Create a new tab in the domain named ", "", "_tpl_doc_new_tab_named_domain"),
        ("Create a new tab in the domain with id ", "", "_tpl_doc_new_tab_id_domain"),
        ("Scrolls the viewport up by ", " pages", "_tpl_doc_scroll_up_pages"),
        ("Scrolls the viewport down by ", " pages", "_tpl_doc_scroll_down_pages"),
        ("Detaches (disconnects from) the domain named `", "`", "_tpl_doc_detach_named_domain"),
        ("Detaches (disconnects from) the domain with id ", "", "_tpl_doc_detach_id_domain"),
        // 通配:"<label> (New Tab)" — head 为空相当于无前缀约束,
        // 必须放最后,否则会吃掉所有以 " (New Tab)" 结尾的字符串。
        ("", " (New Tab)", "_tpl_label_new_tab"),
    ];
    for (head, tail, tpl_key) in PATTERNS {
        if let Some(rest) = key.strip_prefix(*head) {
            if tail.is_empty() && head.is_empty() {
                continue; // 空 head 空 tail 意味着任意字符串都匹配,跳过
            }
            if let Some(value) = rest.strip_suffix(*tail) {
                // 防止过短匹配:value 至少 1 字符才算合理替换
                if value.is_empty() {
                    continue;
                }
                if let Some(tpl) = ordinal_template(locale, tpl_key) {
                    return Some(tpl.replace("{}", value));
                }
            }
        }
    }
    None
}

/// 处理 "Activate Nth Tab/Pane/Window" 这类动态英文 brief。
/// `n` 从 ordinal("1st"/"2nd"/...) 中提取,然后用 ORDINAL_TEMPLATES
/// 查找目标 locale 的模板,把 `{}` 替换为 n。无模板返回 None,t() 继续
/// 兜底返回原 key。
fn try_dynamic_ordinal(key: &str, locale: &str) -> Option<String> {
    const PATTERNS: &[(&str, &str, &str)] = &[
        ("Activate ", " Tab", "_tpl_activate_nth_tab"),
        ("Activate ", " Pane", "_tpl_activate_nth_pane"),
        ("Activate ", " Window", "_tpl_activate_nth_window"),
        // 双占位符,direction 烤入模板 key
        ("Activate the ", " tab to the left", "_tpl_activate_nth_tab_left"),
        ("Activate the ", " tab to the right", "_tpl_activate_nth_tab_right"),
        ("Activate the ", " window backwards", "_tpl_activate_nth_window_back"),
        ("Activate the ", " window forwards", "_tpl_activate_nth_window_forward"),
        ("Switch to ", " next workspace", "_tpl_switch_workspace_next"),
        ("Switch to ", " previous workspace", "_tpl_switch_workspace_prev"),
        // tooltip(doc) 用的 ordinal 模板
        ("Activates the ", " tab", "_tpl_doc_activate_nth_tab"),
        ("Activates the ", " window", "_tpl_doc_activate_nth_window"),
        ("Activates the ", " Pane", "_tpl_doc_activate_nth_pane"),
    ];
    for (head, tail, tpl_key) in PATTERNS {
        if let Some(rest) = key.strip_prefix(*head) {
            if let Some(ord) = rest.strip_suffix(*tail) {
                if let Some(n) = parse_ordinal_prefix(ord) {
                    if let Some(tpl) = ordinal_template(locale, tpl_key) {
                        return Some(tpl.replace("{}", &n.to_string()));
                    }
                }
            }
        }
    }
    None
}

fn parse_ordinal_prefix(s: &str) -> Option<u32> {
    let digits: String = s.chars().take_while(|c| c.is_ascii_digit()).collect();
    if digits.is_empty() {
        return None;
    }
    let suffix = &s[digits.len()..];
    // 只接受 st / nd / rd / th 这 4 个英文 ordinal 后缀
    matches!(suffix, "st" | "nd" | "rd" | "th").then(|| ())?;
    digits.parse().ok()
}

fn ordinal_template(locale: &str, tpl_key: &str) -> Option<&'static str> {
    ORDINAL_TEMPLATES
        .iter()
        .find(|(loc, k, _)| *loc == locale && *k == tpl_key)
        .map(|(_, _, v)| *v)
}

