fn build_table() -> HashMap<&'static str, HashMap<&'static str, &'static str>> {
    let mut m: HashMap<&'static str, HashMap<&'static str, &'static str>> = HashMap::new();

    m.insert("zh-CN", entries(ZH_CN));
    m.insert("zh-TW", entries(ZH_TW));
    m.insert("ja", entries(JA));
    m.insert("ko", entries(KO));
    m.insert("fr", entries(FR));
    m.insert("de", entries(DE));
    m.insert("es", entries(ES));
    m.insert("pt-BR", entries(PT_BR));
    m.insert("pt", entries(PT));
    m.insert("it", entries(IT));
    m.insert("ru", entries(RU));
    m.insert("uk", entries(UK));
    m.insert("pl", entries(PL));
    m.insert("cs", entries(CS));
    m.insert("hu", entries(HU));
    m.insert("ro", entries(RO));
    m.insert("nl", entries(NL));
    m.insert("sv", entries(SV));
    m.insert("nb", entries(NB));
    m.insert("da", entries(DA));
    m.insert("fi", entries(FI));
    m.insert("el", entries(EL));
    m.insert("ar", entries(AR));
    m.insert("he", entries(HE));
    m.insert("tr", entries(TR));
    m.insert("hi", entries(HI));
    m.insert("id", entries(ID));
    m.insert("ms", entries(MS));
    m.insert("fil", entries(FIL));
    m.insert("vi", entries(VI));
    m.insert("th", entries(TH));

    // 合并补充翻译(每国 const 之外新增的高频 brief)
    for (loc, key, val) in EXTRA {
        m.entry(*loc).or_insert_with(HashMap::new).insert(*key, *val);
    }
    // 第二批补漏(format! 但取值有限的"伪动态" brief 等)
    for (loc, key, val) in EXTRA_BRIEFS_2 {
        m.entry(*loc).or_insert_with(HashMap::new).insert(*key, *val);
    }

    m
}

fn entries(table: &'static [(&'static str, &'static str)]) -> HashMap<&'static str, &'static str> {
    table.iter().copied().collect()
}

