#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn locale_normalization() {
        // 通过临时变量测试 normalization 逻辑
        let raw = "zh_CN.UTF-8";
        let no_codeset = raw.split('.').next().unwrap();
        assert_eq!(no_codeset.replace('_', "-"), "zh-CN");
    }

    #[test]
    fn translation_table_has_all_31_locales() {
        let table = translation_table();
        let expected = [
            "zh-CN", "zh-TW", "ja", "ko", "fr", "de", "es", "pt-BR", "pt", "it",
            "ru", "uk", "pl", "cs", "hu", "ro", "nl", "sv", "nb", "da", "fi", "el",
            "ar", "he", "tr", "hi", "id", "ms", "fil", "vi", "th",
        ];
        assert_eq!(table.len(), 31, "应该有 31 个 locale");
        for k in &expected {
            assert!(table.contains_key(k), "缺少 locale: {}", k);
        }
    }

    #[test]
    fn each_locale_has_30_plus_keys() {
        let table = translation_table();
        for (locale, m) in table.iter() {
            assert!(
                m.len() >= 30,
                "locale {} 字符串数 {} 少于 30",
                locale,
                m.len()
            );
        }
    }

    #[test]
    fn fallback_to_english_for_unknown_locale() {
        // 因为 current_locale() 是 OnceLock 缓存,无法在测试中改变
        // 但 t() 对未匹配 key 应返回原 key
        let result = t("__definitely_unknown_key__");
        assert_eq!(result, "__definitely_unknown_key__");
    }
}
